const body = $input.first().json;
try {
  const msg = body.entry[0].changes[0].value.messages[0];
  const text = msg.text.body;
  if (!text || !text.trim()) throw new Error('missing text');
  return [{ json: { from: msg.from, text: text.trim(), valid: true } }];
} catch (e) {
  return [{ json: { valid: false, error: 'malformed payload: missing message fields' } }];
}

const text = ($input.first().json.text || '').toLowerCase();
const has = function () { const words = Array.prototype.slice.call(arguments); return words.some(function (w) { return text.includes(w); }); };
let intent = 'human';
let understood = true;
if (has('human', 'agent', 'person', 'call me', 'speak to', 'complaint', 'representative')) { intent = 'human'; }
else if (has('price', 'cost', 'how much', 'rate', 'pricing', 'charge')) { intent = 'price'; }
else if (has('hours', 'open', 'opening', 'timing', 'close', 'closed', 'when')) { intent = 'hours'; }
else { intent = 'human'; understood = false; }
return [{ json: Object.assign({}, $input.first().json, { intent: intent, understood: understood }) }];

const item = $input.first().json;
const intent = item.intent || 'human';
const replies = {
  price: 'Hello from Demo Traders (demo reply). Our standard pack is listed at Rs 100 in this demo. Reply PRICE LIST for the full demo list, or ask for a human if you need help choosing.',
  hours: 'Hello from Demo Traders (demo reply). Our demo opening hours are Monday to Saturday, 9am to 7pm. We are closed on Sundays in this demo.',
  human: 'Thanks for your message. I have marked this for a human at Demo Traders. A person will reply during demo business hours. (Simulated handoff - no human was contacted.)'
};
const understood = item.understood !== false;
const body = understood ? replies[intent] : 'Sorry, I did not understand that question in this demo. I have marked it for a human at Demo Traders - a person will reply during demo business hours. (Simulated handoff - no human was contacted.)';
return [{ json: { to: item.from, body: body, intent: intent, simulated: true, responder: 'MOCK' } }];
